-- live-only: needs Supabase's pg_cron, pg_net, pgcrypto and Vault (the database tests skip this file).
--
-- Secrets stay inside Supabase: the cron secret is generated here and the push signing keys
-- are generated by the `remind` function on its first run; all are kept in Vault.
create extension if not exists pg_cron;
create extension if not exists pg_net;  -- lands in public on this project (Supabase advises extensions; harmless here)

select vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'stonebook_cron_secret',
                           'Shared by pg_cron and the remind Edge Function')
 where not exists (select 1 from vault.secrets where name = 'stonebook_cron_secret');

-- Read and store Stonebook's secrets; for the remind function only (service role).
create or replace function public.stonebook_secret(p_name text) returns text
language sql stable security definer set search_path = '' as $$
  select decrypted_secret from vault.decrypted_secrets where name = 'stonebook_' || p_name
$$;

-- Stores the push key pair once, both halves together; a second caller keeps the first pair.
create or replace function public.stonebook_store_vapid(p_public text, p_private text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform pg_advisory_xact_lock(hashtext('stonebook_vapid'));
  if not exists (select 1 from vault.secrets where name = 'stonebook_vapid_private') then
    perform vault.create_secret(p_private, 'stonebook_vapid_private');
    perform vault.create_secret(p_public, 'stonebook_vapid_public');
  end if;
end $$;

-- The public half of the push key, for phones to subscribe with (public by design).
create or replace function public.push_public_key() returns text
language sql stable security definer set search_path = '' as $$
  select decrypted_secret from vault.decrypted_secrets where name = 'stonebook_vapid_public'
$$;

revoke all on function public.stonebook_secret(text), public.stonebook_store_vapid(text, text), public.push_public_key()
  from public, anon, authenticated;
grant execute on function public.stonebook_secret(text), public.stonebook_store_vapid(text, text) to service_role;
grant execute on function public.push_public_key() to authenticated;

-- Every 15 minutes, ask the `remind` function to send what's due.
select cron.schedule(
  'stonebook-reminders',
  '*/15 * * * *',
  $$
  select net.http_post(
    url := 'https://qiddytmxiftsvmwoisuc.supabase.co/functions/v1/remind',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', (select decrypted_secret from vault.decrypted_secrets where name = 'stonebook_cron_secret')
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );
  $$
);
